#include "gameos/core/VirtualFileSystem.hpp"
#include <fstream>
namespace gameos::core{std::filesystem::path VirtualFileSystem::resolve(const std::filesystem::path&r)const{return(root_/r).lexically_normal();}bool VirtualFileSystem::exists(const std::filesystem::path&r)const{return std::filesystem::exists(resolve(r));}bool VirtualFileSystem::writeText(const std::filesystem::path&r,const std::string&t){auto p=resolve(r);std::error_code e;std::filesystem::create_directories(p.parent_path(),e);if(e)return false;std::ofstream o(p);if(!o)return false;o<<t;return static_cast<bool>(o);}std::optional<std::string>VirtualFileSystem::readText(const std::filesystem::path&r)const{std::ifstream i(resolve(r));if(!i)return std::nullopt;return std::string((std::istreambuf_iterator<char>(i)),{});}}
